function formatarDocumento(numero) {
  if (!numero) return null;
  const digitos = numero.replace(/\D/g, '');
  if (digitos.length === 14) {
    return digitos.replace(/^(\d{2})(\d{3})(\d{3})(\d{4})(\d{2})$/, '$1.$2.$3/$4-$5');
  }
  if (digitos.length === 11) {
    return digitos.replace(/^(\d{3})(\d{3})(\d{3})(\d{2})$/, '$1.$2.$3-$4');
  }
  return numero;
}

function formatarValorNumero(valor) {
  if (!valor) return null;
  const numero = parseFloat(String(valor).replace(',', '.'));
  return isNaN(numero) ? null : numero;
}

function validarCNPJ(cnpj) {
  if (!cnpj) return null;
  const d = cnpj.replace(/\D/g, '');
  if (d.length !== 14 || /^(\d)\1{13}$/.test(d)) return false;
  const calc = (base, pesos) => {
    let soma = 0;
    for (let i = 0; i < pesos.length; i++) soma += parseInt(base[i]) * pesos[i];
    const resto = soma % 11;
    return resto < 2 ? 0 : 11 - resto;
  };
  const p1 = [5,4,3,2,9,8,7,6,5,4,3,2];
  const p2 = [6,5,4,3,2,9,8,7,6,5,4,3,2];
  const dv1 = calc(d.substring(0,12), p1);
  const dv2 = calc(d.substring(0,12) + dv1, p2);
  return d === d.substring(0,12) + dv1.toString() + dv2.toString();
}

function validarCPF(cpf) {
  if (!cpf) return null;
  const d = cpf.replace(/\D/g, '');
  if (d.length !== 11 || /^(\d)\1{10}$/.test(d)) return false;
  const calc = (base, fatorInicial) => {
    let soma = 0;
    for (let i = 0; i < base.length; i++) soma += parseInt(base[i]) * (fatorInicial - i);
    const resto = (soma * 10) % 11;
    return resto === 10 ? 0 : resto;
  };
  const dv1 = calc(d.substring(0,9), 10);
  const dv2 = calc(d.substring(0,9) + dv1, 11);
  return d === d.substring(0,9) + dv1.toString() + dv2.toString();
}

function diasAtePartirDeHoje(dataStr) {
  if (!dataStr) return null;
  const [dia, mes, ano] = dataStr.split('/').map(Number);
  if (!dia || !mes || !ano) return null;
  const data = new Date(ano, mes - 1, dia);
  const hoje = new Date();
  hoje.setHours(0,0,0,0);
  return Math.round((data - hoje) / (1000 * 60 * 60 * 24));
}

const items = [];
for (const item of $input.all()) {
  let raw = item.json.text || item.json.output || '';
  raw = raw.replace(/```json/g, '').replace(/```/g, '').trim();
  let parsed = {};
  try {
    parsed = JSON.parse(raw);
  } catch (e) {
    parsed = { erro_parse: true, texto_bruto: raw };
  }

  const alertas = [];

  // --- Data de vencimento ---
  if (!parsed.data_vencimento) {
    alertas.push('Sem data de vencimento');
  } else {
    const dias = diasAtePartirDeHoje(parsed.data_vencimento);
    if (dias !== null && Math.abs(dias) <= 2) {
      alertas.push('Data muito próxima de hoje - conferir se não é chute da IA');
    }
  }

  // --- Fornecedor ---
  if (!parsed.nome_fornecedor) {
    alertas.push('SEM FORNECEDOR - revisar PDF manualmente');
  }
  if (parsed.nome_fornecedor && parsed.empresa_pagadora &&
      parsed.nome_fornecedor.trim().toLowerCase() === parsed.empresa_pagadora.trim().toLowerCase()) {
    alertas.push('Fornecedor e pagador iguais - possível erro de extração');
  }

  // --- Valor ---
  if (!parsed.valor) alertas.push('Sem valor');

  // --- CNPJ/CPF do pagador ---
  const doc = parsed.cnpj_pagador ? parsed.cnpj_pagador.replace(/\D/g, '') : '';
  if (!doc) {
    alertas.push('Sem CNPJ/CPF do pagador');
  } else if (doc.length === 14) {
    if (validarCNPJ(doc) === false) alertas.push('CNPJ do pagador com dígito verificador inválido');
  } else if (doc.length === 11) {
    if (validarCPF(doc) === false) alertas.push('CPF do pagador com dígito verificador inválido');
  } else {
    alertas.push('CNPJ/CPF do pagador com quantidade de dígitos incorreta');
  }

  // --- Código de barras ---
  if (!parsed.codigo_barras) {
    alertas.push('Sem código de barras');
  } else {
    const cb = parsed.codigo_barras.replace(/\D/g, '');
    if (cb.length < 44 || cb.length > 48) alertas.push('Código de barras com tamanho incorreto (' + cb.length + ' dígitos)');
  }

  // --- PIX Copia e Cola ---
  if (parsed.pix_copia_cola && !parsed.pix_copia_cola.startsWith('000201')) {
    alertas.push('PIX Copia e Cola com formato suspeito - conferir');
  }

  items.push({
    json: {
      data_vencimento: parsed.data_vencimento || null,
      nome_fornecedor: parsed.nome_fornecedor || null,
      valor: formatarValorNumero(parsed.valor),
      empresa_pagadora: parsed.empresa_pagadora || null,
      cnpj_pagador: formatarDocumento(parsed.cnpj_pagador),
      codigo_barras: parsed.codigo_barras || null,
      pix_copia_cola: parsed.pix_copia_cola || null,
      alertas: alertas.length > 0 ? alertas.join(' | ') : 'OK'
    }
  });
}
return items;

const staticData = $getWorkflowStaticData('global');
const updateId = $input.first().json.update_id;

if (!staticData.processedUpdates) {
  staticData.processedUpdates = [];
}

if (staticData.processedUpdates.includes(updateId)) {
  // Já processamos esse update antes - ignora (retorna vazio, não segue adiante)
  return [];
}

// Marca como processado e limita a lista aos últimos 100 (evita crescer infinito)
staticData.processedUpdates.push(updateId);
if (staticData.processedUpdates.length > 100) {
  staticData.processedUpdates.shift();
}

return $input.all();
